        // 提取对话文本的函数
        function extractDialogues(text) {
            const dialoguesMatch = text.match(/<gamedialogues>([\s\S]*?)<\/gamedialogues>/);
            return dialoguesMatch ? dialoguesMatch[1] : '';
        }
        // 提取选择选项的函数
        function extractChoices(text) {
            const choicesMatch = text.match(/<gamechoices>([\s\S]*?)<\/gamechoices>/);
            return choicesMatch ? choicesMatch[1].trim().split('\n').map(choice => choice.slice(1, -1)) : [];
        }
        // 提取userData的函数
       function extractUserData(text) {
            const userDataMatch = text.match(/<userdata>([\s\S]*?)<\/userdata>/);
            if (userDataMatch) {
                const userData = userDataMatch[1].trim().split('\n').map(item => {
                    const [attr, value] = item.slice(1, -1).split('|');
                    return { attr, value: parseInt(value) };
                });
                return userData;
            }
            return [];
        }
        const userData = extractUserData(gameText);
        // 提取CharaData的函数
        function extractCharaData(text) {
            const charaDataMatch = text.match(/<charadata>([\s\S]*?)<\/charadata>/);
            if (charaDataMatch) {
                const charaData = charaDataMatch[1].trim().split('\n').map(item => {
                    const [name, liking, twisted] = item.slice(1, -1).split('|');
                    return { name, liking: parseInt(liking), twisted: parseInt(twisted) };
                });
                return charaData;
            }
            return [];
        }
        const charaData = extractCharaData(gameText);
