        // 监听窗口尺寸变化
        window.addEventListener('resize', () => {
            const newWindowWidth = window.innerWidth;
            if (newWindowWidth <= 320) { // 针对3.5英寸左右的小屏幕
                gameContainer.style.width = '90vw';
                gameContainer.style.height = '50vw';
                dialogueBox.style.bottom = '10px';
                dialogueBox.style.height = '25%';
            } else if (newWindowWidth > 320 && newWindowWidth <= 768) { // 针对较大的手机和平板
                gameContainer.style.width = '90vw';
                gameContainer.style.height = '50vw';
            } else { // 针对更大的屏幕，如桌面显示器
                gameContainer.style.width = '80vw';
                gameContainer.style.height = '45vw';
            }
        });
    </script>
