        characterLayer.addEventListener('mouseup', () => {
            clearTimeout(pressTimer);
            if (isZoomed) toggleZoom();
        });
        characterLayer.addEventListener('mouseleave', () => {
            clearTimeout(pressTimer);
            if (isZoomed) toggleZoom();
        });
        //防止选中文本框中的文字
        document.getElementById('dialogue-box').addEventListener('mousedown', function(e) {
           e.preventDefault();
        });
const gameContainer = document.getElementById('game-container');
        const dialogueBox = document.getElementById('dialogue-box');

        // 获取当前窗口尺寸
        const windowWidth = window.innerWidth;

        // 根据屏幕尺寸设置样式
        if (windowWidth <= 320) { // 针对3.5英寸左右的小屏幕
            gameContainer.style.width = '90vw';
            gameContainer.style.height = '50vw';
            dialogueBox.style.bottom = '10px';
            dialogueBox.style.height = '25%';
        } else if (windowWidth > 320 && windowWidth <= 768) { // 针对较大的手机和平板
            gameContainer.style.width = '90vw';
            gameContainer.style.height = '50vw';
        } else { // 针对更大的屏幕，如桌面显示器
            gameContainer.style.width = '80vw';
            gameContainer.style.height = '45vw';
        }

        // 监听窗口尺寸变化
        window.addEventListener('resize', () => {
            const newWindowWidth = window.innerWidth;
            if (newWindowWidth <= 320) { // 针对3.5英寸左右的小屏幕
                gameContainer.style.width = '90vw';
                gameContainer.style.height = '50vw';
                dialogueBox.style.bottom = '10px';
                dialogueBox.style.height = '25%';
            } else if (newWindowWidth > 320 && newWindowWidth <= 768) { // 针对较大的手机和平板
                gameContainer.style.width = '90vw';
                gameContainer.style.height = '50vw';
            } else { // 针对更大的屏幕，如桌面显示器
                gameContainer.style.width = '80vw';
                gameContainer.style.height = '45vw';
            }
        });
    </script>
</body>
</html>
